if(!exists('build_customer_household_graph'))library(creditratingsystem)
rf_asof<-'2024-01-31'
rf_entities<-function(){ids<-c('a','b','g','h','h2','f','f2','app');types<-c('CUSTOMER','CUSTOMER','CUSTOMER','HOUSEHOLD','HOUSEHOLD','FACILITY','FACILITY','APPLICATION');lapply(seq_along(ids),function(i)list(entity_id=ids[i],entity_type=types[i],known_at='2024-01-01'))}
rf_edge<-function(id,source,target,role,share=NULL,legal=NULL)list(relationship_id=id,release_seq=1,source_id=source,target_id=target,role=role,effective_from='2024-01-01',effective_until=NULL,known_at='2024-01-01',liability_fraction=legal,budget_share=share,evidence_reference='explicit signed account relation')
rf_relationships<-function()list(rf_edge('ah','a','h','MEMBER_OF'),rf_edge('bh','b','h','MEMBER_OF'),rf_edge('gh','g','h2','MEMBER_OF'),rf_edge('af','a','f','BORROWER_ON',.5,1),rf_edge('bf','b','f','BORROWER_ON',.5,1),rf_edge('gf','g','f','GUARANTOR_ON',0,.25),rf_edge('aa','a','app','COAPPLICANT_ON'),rf_edge('ba','b','app','COAPPLICANT_ON'))
rf_graph<-function(rows=rf_relationships(),asof=rf_asof)build_customer_household_graph(rf_entities(),rows,asof,asof)
rf_obligation<-function(id='f',amount=100)list(facility_id=id,release_seq=1,known_at='2024-01-01',observed_at='2024-01-01',source_id='bank',debt_stock=amount,scheduled_debt_service=amount/10,currency='EUR',period='month',status='ACTIVE')
rf_coverage<-function(status='COMPLETE')list(status=status,sources=list('bank'),known_at='2024-01-01')
rf_aggregate<-function(rows=list(rf_obligation()),g=rf_graph(),status='COMPLETE',policy='exclude')aggregate_household_obligations(rows,g,rf_coverage(status),'EUR','month',policy)
rf_error<-function(code,expr){e<-tryCatch({force(expr);NULL},error=identity);stopifnot(inherits(e,'creditratingsystem_error'),identical(e$code,code))}
r<-rf_aggregate()$value;h<-r$households[[1]];stopifnot(identical(h$facility_ids,list('f')),h$known_linked_debt_stock==100,h$total_budget_debt_service==10,identical(vapply(r$person_legal_liabilities,`[[`,numeric(1),'legal_debt_stock'),c(100,100,25)),length(r$households[[2]]$facility_ids)==0);stopifnot(rf_aggregate(policy='include_declared_share')$value$households[[2]]$known_linked_debt_stock==100,rf_aggregate(policy='include_declared_share')$value$households[[2]]$total_budget_debt_stock==0)
rows<-rf_relationships();revision<-rows[[1]];revision$release_seq<-2;revision$effective_until<-'2024-01-15';revision$known_at<-'2024-01-20';new<-rf_edge('ah2','a','h2','MEMBER_OF');new$effective_from<-'2024-01-15';new$known_at<-'2024-01-20';rows<-c(rows,list(revision,new));stopifnot(rf_graph(rows,'2024-01-16')$value$memberships[[1]]$household_id=='h',rf_graph(rows,'2024-01-21')$value$memberships[[1]]$household_id=='h2');rows[[9]]$known_at<-'2024-01-15';rows[[10]]$known_at<-'2024-01-15';stopifnot(rf_graph(rows,'2024-01-15')$value$memberships[[1]]$household_id=='h2')
h<-rf_aggregate(status='UNKNOWN')$value$households[[1]];stopifnot(h$known_linked_debt_stock==100,is.null(h$total_linked_debt_stock));h<-rf_aggregate(rows=list())$value$households[[1]];stopifnot(h$known_linked_debt_stock==0,identical(h$uncertain_facility_ids,list('f')),is.null(h$total_linked_debt_stock));rows<-c(rf_relationships(),list(rf_edge('af2','a','f2','BORROWER_ON',1,1)));h<-rf_aggregate(list(rf_obligation(),rf_obligation('f2',30)),rf_graph(rows))$value$households[[1]];stopifnot(h$total_linked_debt_stock==130);row<-rf_obligation();row['scheduled_debt_service']<-list(NULL);stopifnot(is.null(rf_aggregate(list(row))$value$households[[1]]$total_linked_debt_service),rf_aggregate(list(row))$value$households[[1]]$total_linked_debt_stock==100)
rf_error('DOUBLE_COUNTING',rf_graph(c(rf_relationships(),list(rf_edge('duplicate','a','h','MEMBER_OF')))));rows<-rf_relationships();rows[[4]]$budget_share<-.8;rf_error('RETAIL_LIABILITY',rf_graph(rows));g<-rf_graph()$value;g$memberships[[1]]$household_id<-'h2';rf_error('INTEGRITY_ERROR',rf_aggregate(g=g));future<-rf_obligation();future$release_seq<-2;future$debt_stock<-0;future$known_at<-'2024-02-01';stopifnot(rf_aggregate(list(rf_obligation(),future))$value$households[[1]]$known_linked_debt_stock==100)
rf_schema<-function(){field<-function(name,type='string',nullable=FALSE)list(name=name,type=type,nullable=nullable);spec<-function(name,key,extra)list(table=name,role=if(name=='customers')'IDENTITY'else 'FEATURE',primary_key=list(key),fields=c(list(field(key),field('observed_at','date'),field('known_at','date')),extra),foreign_keys=list(),date_order=list(list('observed_at','known_at')),event_field='observed_at',known_field='known_at',feature_fields=list(),allow_extra_fields=FALSE);customer<-spec('customers','customer_id',list());application<-spec('applications','application_id',list(field('customer_id'),field('income','number',TRUE)));application$foreign_keys<-list(list(field='customer_id',table='customers',target_field='customer_id'));application$feature_fields<-list('income');list(schema_version='1.0',contract_id='bank',version='1',table_specs=list(customer,application),prohibited_feature_fields=list('booked_amount'),source_coverage=list(list(source_id='bureau',status='UNKNOWN',known_at='2024-01-01')))}
rf_tables<-function()list(customers=list(list(customer_id='a',observed_at='2024-01-01',known_at='2024-01-01')),applications=lapply(1:2,function(i)list(application_id=paste0('app',i),customer_id='a',observed_at='2024-01-02',known_at='2024-01-02',income=NULL)))
r<-validate_retail_dataset(rf_tables(),rf_schema(),rf_asof,rf_asof)$value;stopifnot(r$valid,r$row_counts$applications==2,r$source_coverage[[1]]$status=='UNKNOWN');rows<-rf_tables();rows$customers[[1]]$known_at<-'2024-02-01';r<-validate_retail_dataset(rows,rf_schema(),rf_asof,rf_asof)$value;stopifnot(identical(vapply(r$violations,`[[`,character(1),'code'),rep('PARENT_NOT_KNOWN_AT_CUTOFF',2)))
contract<-rf_schema();contract$table_specs[[2]]$fields[[6]]<-list(name='future_default',type='boolean',nullable=TRUE);contract$table_specs[[2]]$feature_fields[[2]]<-'future_default';r<-validate_retail_dataset(rf_tables(),contract,rf_asof,rf_asof)$value;stopifnot(!r$valid,r$violations[[1]]$code=='OUTCOME_AS_FEATURE');rows<-rf_tables();rows$applications[[2]]$application_id<-'app1';rows$applications[[1]]$known_at<-'2023-12-31';r<-validate_retail_dataset(rows,rf_schema(),rf_asof,rf_asof)$value;stopifnot(setequal(vapply(r$violations,`[[`,character(1),'code'),c('DATE_ORDER','DUPLICATE_KEY')))
cat('Native retail foundations independent oracles PASS\n')
contract<-rf_schema();spec<-contract$table_specs[[2]];spec$table<-'payments';spec$primary_key<-list('payment_id');spec$fields<-list(list(name='payment_id',type='string',nullable=FALSE),list(name='reverses_payment_id',type='string',nullable=TRUE),list(name='observed_at',type='date',nullable=FALSE),list(name='known_at',type='date',nullable=FALSE));spec$foreign_keys<-list(list(field='reverses_payment_id',table='payments',target_field='payment_id'));spec$feature_fields<-list();contract$table_specs<-list(spec);payment<-list(payment_id='p',reverses_payment_id=NULL,observed_at='2024-01-10',known_at='2024-02-01');reversal<-list(payment_id='r',reverses_payment_id='p',observed_at='2024-01-20',known_at='2024-01-20');r<-validate_retail_dataset(list(payments=list(payment,reversal)),contract,rf_asof,rf_asof)$value;stopifnot(length(r$violations)==1,r$violations[[1]]$row_index==1,r$violations[[1]]$code=='PARENT_NOT_KNOWN_AT_CUTOFF');payment$known_at<-'2024-01-10';stopifnot(validate_retail_dataset(list(payments=list(payment,reversal)),contract,rf_asof,rf_asof)$value$valid);rf_error('TARGET_MISMATCH',build_customer_household_graph(rf_entities(),rf_relationships(),rf_asof,rf_asof,context=list(known_at='2024-01-30')))
